    if (pr.draft) continue;
    var labels = labelNames(pr);
    var headSha = pr.head && (pr.head.sha || pr.head);
    if (!headSha) continue;
    if (labels.indexOf('blocked') !== -1) continue; // #939: owner-parked — the bot ignores it even when green

