        assert.equal(rule.query.threadsResolved, false, 'still the unresolved-threads complement');
        assert.equal((rule.query.notLabels || []).indexOf('pr_approved'), -1,
            'pr_approved must NOT exclude the rework arm (gh-710 deadlock)');
