    let data = null;
    if (repliesJson) {
        try {
            data = JSON.parse(repliesJson);
        } catch (e) {
            console.warn('Failed to parse review_replies.json:', e.message || e);
        }
    }

    const replies = (data && data.replies) ? data.replies : [];
    if (replies.length === 0) {
